 EXEC sys.sp_executesql N'CREATE PROCEDURE dbo.usp_read_customer_cards
 @customer_id bigint=NULL,@search nvarchar(120)=N'''',@page int=1,@page_size int=25,@status nvarchar(12)=N''all'',@quarantine nvarchar(12)=N''all''
 WITH EXECUTE AS OWNER AS BEGIN
 SET NOCOUNT ON;
 IF @@TRANCOUNT=0 OR NOT EXISTS(SELECT 1 FROM sys.dm_exec_sessions WHERE session_id=@@SPID AND transaction_isolation_level=4) THROW 51076,''CUSTOMER_CARD_READ_TRANSACTION_REQUIRED'',1;
 IF @page IS NULL OR @page<1 OR @page>1000000 OR @page_size IS NULL OR @page_size<1 OR @page_size>100 OR @search IS NULL OR @status IS NULL OR @status NOT IN(N''all'',N''active'',N''passive'') OR @quarantine IS NULL OR @quarantine NOT IN(N''all'',N''included'',N''excluded'') OR (@customer_id IS NOT NULL AND @customer_id<1) THROW 51076,''CUSTOMER_CARD_QUERY_INVALID'',1;
 IF DB_NAME()<>N''MELISA_ERP_SIRKET_TEST_20260929_01'' OR CONVERT(nvarchar(128),SERVERPROPERTY(''ServerName''))<>N''Semih\MELISADEV'' THROW 51076,''CUSTOMER_CARD_TARGET_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.runs WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND status=N''COMMITTED'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'') THROW 51076,''CUSTOMER_CARD_SOURCE_UNAVAILABLE'',1;
IF (SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(name,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(object_id)),2),N''|'',is_disabled,N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger''),N''|'',OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger''))),N'';'') WITHIN GROUP(ORDER BY name)),2) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' OR name LIKE N''immutable[_]operation[_]%'' OR name LIKE N''immutable[_]accepted[_]%'')<>''9AE41CA1AB25EE165019AD04DBD9A6FB4E5B7190F027E0A07A87FB03D698379E'' THROW 51076,''CUSTOMER_CARD_GUARD_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM sys.triggers WHERE name LIKE N''operation[_]quarantine[_]%'' AND is_disabled=0 AND OBJECTPROPERTY(object_id,''ExecIsFirstInsertTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstUpdateTrigger'')=1 AND OBJECTPROPERTY(object_id,''ExecIsFirstDeleteTrigger'')=1)<>37 THROW 51076,''CUSTOMER_CARD_QUARANTINE_UNAVAILABLE'',1;
IF NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_manifest WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND source_hash=''36971dab7296dd171ee0084c185f833b47b96d6a47fe57c8486a2b81d78ef400'' AND plan_hash=''18639c27f276f4263d5e9a6b5037753c78f2c3d341a053055db7cb7b00da2f0a'' AND source_as_of=N''2026-09-30'' AND sealed=1 AND seal_hash=''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' AND source_rows=176 AND native_holds=172 AND not_present=4) THROW 51076,''CUSTOMER_CARD_QUARANTINE_UNAVAILABLE'',1;
IF (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds)<>176 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NOT NULL)<>172 OR (SELECT COUNT(*) FROM erp_migration.operation_quarantine_holds WHERE native_id IS NULL)<>4 OR EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.entity,h.source_key,h.source_id,h.source_company,h.source_code,h.source_name,h.native_id,h.native_entity_id,h.native_source_key,h.native_code,h.native_name,h.status,h.reasons_json,h.binding_basis FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2)<>h.row_hash) THROW 51076,''CUSTOMER_CARD_QUARANTINE_BINDING_DRIFT'',1;
IF LOWER(CONVERT(char(64),HASHBYTES(''SHA2_256'',(SELECT h.source_key,h.row_hash FROM erp_migration.operation_quarantine_holds h ORDER BY h.source_key FOR JSON PATH)),2))<>''69ff490f2938e34aa2f10399a5cf7b8042950667780779a15d708188c4b90de7'' THROW 51076,''CUSTOMER_CARD_QUARANTINE_BINDING_DRIFT'',1;
IF (SELECT COUNT(*) FROM erp_migration.records WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND entity IN(N''parties'',N''accounts'') AND JSON_VALUE(payload_json,''$.role'')=N''customer'')<>806 OR
(SELECT CONVERT(varchar(64),HASHBYTES(''SHA2_256'',STRING_AGG(CONVERT(nvarchar(max),CONCAT(entity,N''|'',source_key,N''|'',payload_hash,N''|'',CONVERT(varchar(64),HASHBYTES(''SHA2_256'',payload_json),2))),N'';'') WITHIN GROUP(ORDER BY entity,source_key)),2) FROM erp_migration.records WHERE run_id=N''VEGA-OPENING-TEST-20261004-06'' AND entity IN(N''parties'',N''accounts'') AND JSON_VALUE(payload_json,''$.role'')=N''customer'')<>''4165D239F10C66F0986CE460F8705098FFFF81B0BF3DFF3CAF8DA76037E734C6'' THROW 51076,''CUSTOMER_CARD_STAGE_UNAVAILABLE'',1;
 DECLARE @pattern nvarchar(500)=N''%''+REPLACE(REPLACE(REPLACE(REPLACE(@search,N''~'',N''~~''),N''%'',N''~%''),N''_'',N''~_''),N''['',N''~['')+N''%'';
 WITH eligible AS(SELECT c.* FROM dbo.customers c WHERE c.is_deleted=0 AND (@customer_id IS NULL OR c.id=@customer_id)
 AND (@status=N''all'' OR (@status=N''active'' AND c.is_active=1) OR (@status=N''passive'' AND c.is_active=0))
 AND (@search=N'''' OR c.customer_code LIKE @pattern ESCAPE N''~'' OR c.name LIKE @pattern ESCAPE N''~'' OR c.phone LIKE @pattern ESCAPE N''~'')
 AND (@quarantine=N''all'' OR (@quarantine=N''included'' AND EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE (h.entity=N''customer'' AND h.native_id=c.id) OR (h.native_entity_id=c.party_entity_id AND c.party_entity_id IS NOT NULL) OR EXISTS(SELECT 1 FROM dbo.party_source_links hl WHERE hl.customer_id=c.id AND hl.source_company=h.source_company AND CONVERT(varchar(20),hl.source_id)=h.source_id))) OR (@quarantine=N''excluded'' AND NOT EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds h WHERE (h.entity=N''customer'' AND h.native_id=c.id) OR (h.native_entity_id=c.party_entity_id AND c.party_entity_id IS NOT NULL) OR EXISTS(SELECT 1 FROM dbo.party_source_links hl WHERE hl.customer_id=c.id AND hl.source_company=h.source_company AND CONVERT(varchar(20),hl.source_id)=h.source_id))))),
 paged AS(SELECT * FROM eligible ORDER BY id OFFSET ((@page-1)*@page_size) ROWS FETCH NEXT @page_size ROWS ONLY)
 SELECT (SELECT COUNT(*) FROM eligible) total,CONVERT(varchar(64),HASHBYTES(''SHA2_256'',OBJECT_DEFINITION(@@PROCID)),2) readerDefinitionHash,
 (SELECT JSON_QUERY((SELECT CONVERT(varchar(20),c.id) id,c.customer_code customerCode,c.name customerName,c.phone,c.email,c.address,c.city,c.country,c.currency_code currency,CONVERT(varchar(50),c.balance) scalarBalanceExact,CONVERT(varchar(50),c.risk_limit) riskLimitExact,c.is_active isActive,c.is_deleted isDeleted,CONVERT(varchar(20),c.party_entity_id) partyEntityId,c.source_record_key sourceRecordKey,c.migration_run_id migrationRunId FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)) customer,
 JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),l.id) id,CONVERT(varchar(20),l.party_entity_id) partyEntityId,CONVERT(varchar(20),l.customer_id) customerId,l.source_company sourceCompany,CONVERT(varchar(20),l.source_id) sourceId,l.source_currency sourceCurrency,l.source_record_key sourceRecordKey,l.migration_run_id migrationRunId FROM dbo.party_source_links l WHERE l.customer_id=c.id AND l.supplier_id IS NULL FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) sourceLinks,
 JSON_QUERY(COALESCE((SELECT r.source_key sourceKey,JSON_VALUE(r.payload_json,''$.source_id'') sourceId,JSON_VALUE(r.payload_json,''$.company'') company,JSON_VALUE(r.payload_json,''$.role'') role,JSON_VALUE(r.payload_json,''$.code'') code,JSON_VALUE(r.payload_json,''$.name'') name,JSON_VALUE(r.payload_json,''$.currency_code'') currency,JSON_VALUE(r.payload_json,''$.balance_status'') balanceStatus,JSON_VALUE(JSON_VALUE(r.payload_json,''$.source_payload_json''),''$.scope'') scope,
 (SELECT COUNT(*) FROM dbo.party_source_links gl WHERE gl.source_id=l.source_id AND gl.source_company=l.source_company AND gl.customer_id IS NOT NULL AND gl.supplier_id IS NULL) globalSourceLinkCount
 FROM dbo.party_source_links l JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''parties'' AND JSON_VALUE(r.payload_json,''$.role'')=N''customer'' AND JSON_VALUE(r.payload_json,''$.company'')=l.source_company AND TRY_CONVERT(int,JSON_VALUE(r.payload_json,''$.source_id''))=l.source_id WHERE l.customer_id=c.id AND l.supplier_id IS NULL FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) sourceParties,
 JSON_QUERY(COALESCE((SELECT a.source_key sourceKey,JSON_VALUE(a.payload_json,''$.party_source_key'') partySourceKey,JSON_VALUE(a.payload_json,''$.role'') role,JSON_VALUE(a.payload_json,''$.currency_code'') currency,JSON_VALUE(a.payload_json,''$.balance_status'') balanceStatus,CONVERT(varchar(50),TRY_CONVERT(decimal(28,8),JSON_VALUE(a.payload_json,''$.balance''))) sourceOpeningBalanceExact
 FROM erp_migration.records a WHERE a.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND a.entity=N''accounts'' AND JSON_VALUE(a.payload_json,''$.role'')=N''customer'' AND EXISTS(SELECT 1 FROM dbo.party_source_links l JOIN erp_migration.records r ON r.run_id=N''VEGA-OPENING-TEST-20261004-06'' AND r.entity=N''parties'' AND JSON_VALUE(r.payload_json,''$.role'')=N''customer'' AND JSON_VALUE(r.payload_json,''$.company'')=l.source_company AND TRY_CONVERT(int,JSON_VALUE(r.payload_json,''$.source_id''))=l.source_id WHERE l.customer_id=c.id AND l.supplier_id IS NULL AND JSON_VALUE(a.payload_json,''$.party_source_key'')=r.source_key) FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) sourceAccounts,
 JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),a.id) id,CONVERT(varchar(20),c.id) customerId,CONVERT(varchar(20),a.customer_id) nativeOwnerCustomerId,CONVERT(varchar(20),a.party_entity_id) partyEntityId,a.currency_code currency,CONVERT(varchar(50),a.current_balance) nativeBalanceExact,a.balance_status balanceStatus,a.source_record_key sourceRecordKey,a.migration_run_id migrationRunId,
 CONVERT(varchar(50),(SELECT CASE WHEN SUM(CASE WHEN m.source_record_key IS NULL AND m.cutover_source_key IS NULL AND ISNULL(m.affects_balance,1)=1 AND m.balance_effect_exact IS NULL AND m.balance_effect IS NULL THEN 1 ELSE 0 END)>0 THEN NULL ELSE COALESCE(SUM(CASE WHEN m.source_record_key IS NULL AND m.cutover_source_key IS NULL AND ISNULL(m.affects_balance,1)=1 THEN COALESCE(m.balance_effect_exact,CONVERT(decimal(28,8),m.balance_effect)) ELSE CONVERT(decimal(28,8),0) END),CONVERT(decimal(28,8),0)) END FROM dbo.customer_movements m WHERE m.customer_id=c.id AND COALESCE(m.account_currency,m.currency_code)=a.currency_code)) localDeltaExact,
 CONVERT(varchar(50),(SELECT CASE WHEN SUM(CASE WHEN ISNULL(m.affects_balance,1)=1 AND m.balance_effect_exact IS NULL AND m.balance_effect IS NULL THEN 1 ELSE 0 END)>0 THEN NULL ELSE COALESCE(SUM(CASE WHEN ISNULL(m.affects_balance,1)=1 THEN COALESCE(m.balance_effect_exact,CONVERT(decimal(28,8),m.balance_effect)) ELSE CONVERT(decimal(28,8),0) END),CONVERT(decimal(28,8),0)) END FROM dbo.customer_movements m WHERE m.customer_id=c.id AND COALESCE(m.account_currency,m.currency_code)=a.currency_code)) ledgerBalanceExact
 FROM dbo.party_currency_accounts a WHERE (a.customer_id=c.id OR (a.customer_id IS NULL AND a.party_entity_id=c.party_entity_id)) AND a.supplier_id IS NULL FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) nativeAccounts,
 JSON_QUERY(COALESCE((SELECT h.entity,CONVERT(varchar(20),h.native_id) nativeId,h.source_key sourceKey,h.status,JSON_QUERY(h.reasons_json) reasons FROM erp_migration.operation_quarantine_holds h WHERE (h.entity=N''customer'' AND h.native_id=c.id) OR (h.native_entity_id=c.party_entity_id AND c.party_entity_id IS NOT NULL) OR EXISTS(SELECT 1 FROM dbo.party_source_links hl WHERE hl.customer_id=c.id AND hl.source_company=h.source_company AND CONVERT(varchar(20),hl.source_id)=h.source_id) FOR JSON PATH,INCLUDE_NULL_VALUES),N''[]'')) quarantineHolds
 FROM paged c ORDER BY c.id FOR JSON PATH,INCLUDE_NULL_VALUES) rowsJson;
 END;';
